"""Summarize latency_metrics.csv generated by run_engine.py."""
import argparse
import csv
import math
from pathlib import Path


def percentile(values, p):
    if not values:
        return 0
    ordered = sorted(values)
    index = max(0, min(len(ordered) - 1, math.ceil(p * len(ordered)) - 1))
    return ordered[index]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--file", default="latency_metrics.csv")
    args = parser.parse_args()
    path = Path(args.file)
    if not path.exists():
        parser.error(f"{path} not found; run run_engine.py and generate at least one trade first")

    with path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    latencies = [int(row["latency_ns"]) for row in rows if row.get("latency_ns")]
    if not latencies:
        print("No trade latency samples found.")
        return
    print(f"Samples: {len(latencies):,}")
    print(f"Mean: {sum(latencies) / len(latencies):,.0f} ns")
    print(f"p50: {percentile(latencies, 0.50):,} ns")
    print(f"p95: {percentile(latencies, 0.95):,} ns")
    print(f"p99: {percentile(latencies, 0.99):,} ns")
    print(f"Max: {max(latencies):,} ns")
    print("Note: timing includes the trade callback; it is not pure matching-core latency.")


if __name__ == "__main__":
    main()
